<?php
require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/shu_pinjaman_helper.php';$page_title='SHU Saya';
$s=$db->prepare('SELECT id,kategori_shu FROM anggota WHERE user_id=?');$s->execute([$_SESSION['user_id']]);$member=$s->fetch(PDO::FETCH_ASSOC);if(!$member){http_response_code(404);exit('Data anggota tidak ditemukan.');}
$rows=[];if(shuPinjamanSiap($db)){$s=$db->prepare('SELECT h.*,p.kode_pinjaman,p.tanggal_lunas,src.nama_lengkap sumber_nama FROM shu_hak_pinjaman h JOIN pinjaman p ON p.id=h.pinjaman_id JOIN anggota src ON src.id=h.sumber_anggota_id WHERE h.anggota_id=? ORDER BY h.created_at DESC,h.id DESC');$s->execute([$member['id']]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);}
$total=$paid=0;foreach($rows as $r){$total+=(int)$r['jumlah'];if($r['status_bayar']==='sudah')$paid+=(int)$r['jumlah'];}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SHU Saya</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0/css/all.min.css" rel="stylesheet"></head><body><?php include __DIR__.'/../includes/header.php';?><div class="container-fluid"><div class="row"><?php include __DIR__.'/../includes/sidebar.php';?><main class="col-md-9 ms-sm-auto col-lg-10 px-md-4 py-4"><header class="service-page-heading"><div><span class="service-eyebrow">SHU PINJAMAN</span><h1 class="h3">SHU Saya</h1><p class="text-muted mb-0">Peran Anda: <strong><?= $member['kategori_shu']==='ketua_kelompok'?'Ketua Kelompok':'Anggota' ?></strong>. Hak muncul ketika pinjaman tanpa jaminan lunas.</p></div></header><div class="service-kpi-grid"><article class="service-kpi"><span>Total hak</span><strong><?= formatRupiah($total) ?></strong><small>Seluruh pelunasan dan referensi</small></article><article class="service-kpi"><span>Sudah diterima</span><strong><?= formatRupiah($paid) ?></strong><small>Pembayaran tercatat</small></article><article class="service-kpi"><span>Belum diterima</span><strong><?= formatRupiah($total-$paid) ?></strong><small>Hubungi pengurus koperasi</small></article></div><section class="card"><div class="card-header"><h2 class="h5 mb-0">Riwayat hak SHU</h2></div><div class="card-body"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Pinjaman</th><th>Jenis</th><th>Perhitungan</th><th>Hak</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="text-center text-muted py-4">Belum ada hak SHU pinjaman.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?= layananEscape($r['kode_pinjaman']) ?><br><small><?= layananEscape($r['tanggal_lunas']?:'-') ?></small></td><td><?= $r['jenis']==='referensi'?'Referensi: '.layananEscape($r['sumber_nama']):'Pelunasan pribadi' ?></td><td><?= formatRupiah($r['dasar_pinjaman']) ?> × <?= rtrim(rtrim(number_format($r['persen'],4,'.',''),'0'),'.') ?>%</td><td><strong><?= formatRupiah($r['jumlah']) ?></strong></td><td><span class="badge <?= $r['status_bayar']==='sudah'?'bg-success':'bg-warning text-dark' ?>"><?= $r['status_bayar']==='sudah'?'Sudah dibayar':'Belum dibayar' ?></span></td><td><?php if($r['status_bayar']==='sudah'):?><a class="btn btn-sm btn-outline-primary" href="kwitansi_shu.php?id=<?= (int)$r['id'] ?>">Kwitansi</a><?php else:?><span class="text-muted small">Menunggu Admin</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></section></main></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
